        let source = "function outer()\n    for i = 1:10\n        inner();\n    end\n    function inner()\n        i = 5;\n    end\nend\nclassdef Foo\n    methods\n        function y = ctor(x)\n            y = Foo(Foo(x));\n        end\n    end\nend\n";
