    find_child_of_kind(iter, "range")
}

/// Get the last named child of a node (including `end`).
pub(crate) fn last_named_child(node: Node) -> Option<Node> {
    let mut result = None;
    let count = node.child_count();
    for i in 0..count {
        if let Some(child) = node.child(i) {
            if child.is_named() {
                result = Some(child);
            }
        }
    }
