        "function_call" => get_function_call_name(node, source),
        "command" => get_command_name(node, source),
        _ => return false,
    };
    let func_name = match func_name {
        Some(n) => n,
        None => return false,
    };
    if func_name != "evalin" && func_name != "assignin" {
        return false;
