        "identifier" => Some(node_text(lhs, source).to_string()),
        "function_call" => get_function_call_name(lhs, source).map(|s| s.to_string()),
        "field_expression" => {
            find_child_of_kind(lhs, "identifier").map(|n| node_text(n, source).to_string())
        }
