/// Check whether a `warning` call's first argument is an empty string literal.
pub(crate) fn call_has_empty_string_arg(node: Node, source: &str) -> bool {
    let Some(args) = find_child_of_kind(node, "arguments") else {
        return false;
    };
    let Some(first) = first_named_child(args) else {
        return false;
    };
    if first.kind() != "string" {
        return false;
    }
    let text = node_text(first, source);
    let inner = text.trim().trim_matches(|c| c == '\'' || c == '"');
