```rust
use super::*;

impl GoodPracticesEngine {
    /// COMNC: a `%` comment that follows a comma on the same line.
    pub(crate) fn check_comnc(&self, node: Node, source: &str) -> Vec<Diagnostic> {
        if !self.is_check_enabled("COMNC") || node.kind() != "comment" {
            return Vec::new();
        }

        let text = node_text(node, source);

        // Ignore block comments (%{ ... %}) and pragma comments (%#...).
        if text.starts_with("%{") || text.starts_with("%#") || text.starts_with("%%") {
            return Vec::new();
        }

        // Check the text before the comment on the same line: the last
        // non-whitespace character must be a comma.
        if !comment_follows_comma(node, source) {
            return Vec::new();
        }

        let pos = node.start_position();
        vec![Diagnostic {
            rule_id: "COMNC",
            message: "...".to_string(),
            severity: Severity::Info,
            byte_range: node.start_byte()..node.start_byte() + 2,
            line: pos.row + 1,
            column: pos.column + 1,
            fix: None,
        }]
    }
