        let source = "classdef Foo\n    methods\n        function disp(obj)\n            fprintf('x');\n        end\n    end\nend\n";
        let tree = parse(source);
        let eng = engine();

        let diags = eng.check_display_override(&tree, source);
        assert!(diags.is_empty(), "got: {diags:?}");
    }
}

